<div class="page-heading"><div><div class="eyebrow">CONTROLE DE ACESSO</div><h1>Usuários e permissões</h1><p>Credenciais individuais para cada setor da empresa.</p></div><div class="page-actions"><a href="<?=e(url('users',['new'=>1]))?>#editor" class="btn-aurora"><?=svg_icon('plus',16)?> Novo usuário</a></div></div>
<details class="panel editor" id="editor" <?=($edit||isset($_GET['new']))?'open':''?>><summary><?=$edit?'Editar usuário':'Cadastrar usuário'?></summary><div class="editor-inner"><form method="post" action="<?=e(url('users.save'))?>"><?=csrf_field()?><input type="hidden" name="_back" value="users"><input type="hidden" name="id" value="<?=e($edit['id']??'')?>"><div class="form-grid"><div class="field"><label>Nome completo *</label><input name="name" required value="<?=e($edit['name']??'')?>"></div><div class="field"><label>E-mail *</label><input name="email" type="email" required value="<?=e($edit['email']??'')?>"></div><div class="field"><label>Perfil</label><select name="role"><?php foreach(['admin'=>'Administrador','sales'=>'Comercial','production'=>'Produção','finance'=>'Financeiro'] as $r=>$txt):?><option value="<?=$r?>" <?=($edit['role']??'sales')===$r?'selected':''?>><?=e($txt)?></option><?php endforeach;?></select></div><div class="field"><label>Senha <?= $edit?'(deixe vazia para manter)':'*' ?></label><input name="password" type="password" minlength="10" <?=$edit?'':'required'?> autocomplete="new-password" placeholder="Mínimo de 10 caracteres"></div><div class="field span-2"><label><input type="checkbox" name="active" value="1" <?=($edit['active']??1)?'checked':''?>> Conta ativa</label></div></div><div class="form-footer"><button class="btn-aurora">Salvar usuário</button><a href="<?=e(url('users'))?>" class="btn-aurora btn-outline-aurora">Cancelar</a></div></form></div></details>
<div class="panel"><div class="panel-header"><h2>Equipe cadastrada</h2><span class="tag"><?=count($users)?> usuários</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Usuário</th><th>E-mail</th><th>Perfil</th><th>Situação</th><th>Ações</th></tr></thead><tbody><?php foreach($users as $u):?><tr><td><strong><?=e($u['name'])?></strong><small>Desde <?=e(date_br($u['created_at']))?></small></td><td><?=e($u['email'])?></td><td><?=e(['admin'=>'Administrador','sales'=>'Comercial','production'=>'Produção','finance'=>'Financeiro'][$u['role']])?></td><td><span class="status-badge <?=$u['active']?'badge-success':'badge-muted'?>"><?=$u['active']?'Ativo':'Inativo'?></span></td><td><a class="btn-aurora btn-outline-aurora btn-sm-aurora" href="<?=e(url('users',['edit'=>$u['id']]))?>#editor"><?=svg_icon('edit',14)?> Editar</a></td></tr><?php endforeach;?></tbody></table></div></div>
